// Distributes every row of kStrings into the three per-language maps.
// String literals are stored as UTF-8 bytes, so they are always decoded with
// QString::fromUtf8() (independent of the compiler's source charset).
// Rows where a language column is nullptr are skipped, which makes lookups for
// that language fall back to English.
void loadQuickReportsTranslations(QMap<QString, QMap<QString, QString>> &translations) {
    QMap<QString, QString> &en = translations["en"];
    QMap<QString, QString> &fr = translations["fr"];
    QMap<QString, QString> &zh = translations["zh"];
    for (const Tr &t : kStrings) {
        const QString key = QString::fromUtf8(t.key);
        if (t.en) en.insert(key, QString::fromUtf8(t.en));
        if (t.fr) fr.insert(key, QString::fromUtf8(t.fr));
        if (t.zh) zh.insert(key, QString::fromUtf8(t.zh));
    }
}
